// One input shape for the whole waterfall, whatever the caller sent.
return $input.all().map((item) => {
  const b = item.json.body || item.json;
  let domain = String(b.domain || b.company_domain || '').toLowerCase().trim();
  domain = domain.split('//').pop().split('/')[0];
  if (domain.startsWith('www.')) domain = domain.slice(4);

  const first = String(b.first_name || '').trim();
  const last = String(b.last_name || '').trim();

  return { json: {
    lead_id: b.lead_id || '',
    first_name: first,
    last_name: last,
    full_name: (first + ' ' + last).trim(),
    company: b.company || '',
    domain: domain,
    linkedin_url: b.linkedin_url || '',
    callback_url: b.callback_url || '',
    email: '',
    email_source: '',
    email_status: 'unknown',
    confidence: 0,
    tried: []
  }};
});

// One lead per request - Clay calls this once per row - so there is exactly one item.
// Read Apollo without letting a locked placeholder through as if it were an address.
const lead = Object.assign({}, $('normalise request').first().json);
const person = ($input.first().json || {}).person || {};
const email = String(person.email || '');
const usable = email.includes('@') && !email.includes('email_not_unlocked');

lead.tried = (lead.tried || []).concat(['apollo']);
if (usable) {
  lead.email = email;
  lead.email_source = 'apollo';
}
if (!lead.title && person.title) lead.title = person.title;

return [{ json: lead }];

// Prefer a professional address over a personal one, and skip the grades RocketReach
// itself has no confidence in - a graded-F address is not a finding.
const lead = Object.assign({}, $('read Apollo result').first().json);
const res = $input.first().json || {};
const emails = Array.isArray(res.emails) ? res.emails : [];

const professional = emails.find((e) => e.email && e.type === 'professional' && e.grade !== 'F');
const fallback = emails.find((e) => e.email && e.grade !== 'F');
const picked = professional || fallback;

lead.tried = (lead.tried || []).concat(['rocketreach']);
if (picked) {
  lead.email = picked.email;
  lead.email_source = 'rocketreach';
}

return [{ json: lead }];

// Step 3, and the honest one: a pattern guess is a hypothesis, not a contact.
// It only survives if the verifier independently says the mailbox exists.
return $input.all().map((item) => {
  const lead = Object.assign({}, item.json);
  const f = String(lead.first_name || '').toLowerCase();
  const l = String(lead.last_name || '').toLowerCase();
  const d = lead.domain;

  lead.tried = (lead.tried || []).concat(['pattern']);

  if (f && l && d) {
    lead.email = f + '.' + l + '@' + d;
    lead.email_source = 'pattern';
  }

  return { json: lead };
});

// Confidence combines where the address came from with what the verifier said.
// A pattern guess the verifier will not confirm is discarded, not downgraded - handing
// a client a plausible-looking guess is how a sending domain gets burned.
const statusOf = { valid: 'valid', catchall: 'risky', unknown: 'unknown', disposable: 'invalid', invalid: 'invalid' };
const sourceWeight = { apollo: 70, rocketreach: 65, pattern: 25 };
const statusWeight = { valid: 30, risky: 5, unknown: 0, invalid: -100 };

const lead = Object.assign({}, $('collect candidates').first().json);
const result = String(($input.first().json || {}).result || 'unknown');
const status = statusOf[result] || 'unknown';

let confidence = (sourceWeight[lead.email_source] || 0) + (statusWeight[status] || 0);
if (confidence < 0) confidence = 0;
if (confidence > 100) confidence = 100;

const guessUnconfirmed = lead.email_source === 'pattern' && status !== 'valid';
if (status === 'invalid' || guessUnconfirmed) {
  lead.email = '';
  lead.email_source = '';
  confidence = 0;
}

lead.email_status = lead.email ? status : 'unknown';
lead.confidence = confidence;
lead.stage = lead.email ? 'enriched' : 'new';
lead.enriched_at = new Date().toISOString();

return [{ json: lead }];
